//! ICMPv4 messages generated by the router: echo replies and the error
//! messages required by RFC 792/1191. Received ICMP is otherwise opaque.

const std = @import("std");
const ipv4 = @import("ipv4.zig");

pub const Type = struct {
    pub const echo_reply: u8 = 0;
    pub const destination_unreachable: u8 = 3;
    pub const echo_request: u8 = 8;
    pub const time_exceeded: u8 = 11;
};

pub const Code = struct {
    pub const net_unreachable: u8 = 0;
    pub const host_unreachable: u8 = 1;
    pub const frag_needed: u8 = 4;
    pub const admin_prohibited: u8 = 13;
    pub const ttl_exceeded: u8 = 0;
};

pub const Error = error{
    Truncated,
    NotEchoRequest,
    NoSpace,
};

pub fn writeEchoRequest(buf: []u8, id: u16, seq: u16, payload: []const u8) Error!usize {
    const total = 8 + payload.len;
    if (buf.len < total) return error.NoSpace;

    buf[0] = Type.echo_request;
    buf[1] = 0;
    writeU16(buf, 2, 0);
    writeU16(buf, 4, id);
    writeU16(buf, 6, seq);
    @memcpy(buf[8..total], payload);
    writeU16(buf, 2, ipv4.checksum(buf[0..total]));
    return total;
}

pub fn writeEchoReply(buf: []u8, request: []const u8) Error!usize {
    if (request.len < 8) return error.Truncated;
    if (request[0] != Type.echo_request) return error.NotEchoRequest;

    if (buf.len < request.len) return error.NoSpace;
    @memcpy(buf[0..request.len], request);
    buf[0] = Type.echo_reply;
    writeU16(buf, 2, 0);
    writeU16(buf, 2, ipv4.checksum(buf[0..request.len]));
    return request.len;
}

/// Builds an ICMP error quoting the original IPv4 header and 8 payload bytes.
pub fn writeError(
    buf: []u8,
    typ: u8,
    code: u8,
    original: []const u8,
    rest: u32,
) Error!usize {
    if (original.len < 20) return error.Truncated;

    const ihl = original[0] & 0x0f;
    const header_len: usize = @as(usize, ihl) * 4;
    if (original.len < header_len) return error.Truncated;

    const quoted_len = @min(original.len, header_len + 8);
    const total = 8 + quoted_len;
    if (buf.len < total) return error.NoSpace;

    buf[0] = typ;
    buf[1] = code;
    writeU16(buf, 2, 0);
    writeU32(buf, 4, rest);
    @memcpy(buf[8..total], original[0..quoted_len]);
    writeU16(buf, 2, ipv4.checksum(buf[0..total]));
    return total;
}

fn writeU16(buf: []u8, off: usize, value: u16) void {
    buf[off] = @truncate(value >> 8);
    buf[off + 1] = @truncate(value);
}

fn writeU32(buf: []u8, off: usize, value: u32) void {
    buf[off] = @truncate(value >> 24);
    buf[off + 1] = @truncate(value >> 16);
    buf[off + 2] = @truncate(value >> 8);
    buf[off + 3] = @truncate(value);
}

const testing = std.testing;

test "icmp echo reply mirrors request" {
    var request: [64]u8 = undefined;
    const n = try writeEchoRequest(&request, 0x1234, 7, "payload");

    var reply: [64]u8 = undefined;
    const m = try writeEchoReply(&reply, request[0..n]);

    try testing.expectEqual(n, m);
    try testing.expectEqual(Type.echo_reply, reply[0]);
    try testing.expectEqual(@as(u16, 0), ipv4.checksum(reply[0..m]));
    try testing.expectEqualSlices(u8, request[8..n], reply[8..m]);
}

test "icmp echo reply rejects non-requests" {
    var buf: [16]u8 = @splat(0);
    try testing.expectError(error.Truncated, writeEchoReply(&buf, buf[0..7]));

    buf[0] = Type.echo_reply;
    try testing.expectError(error.NotEchoRequest, writeEchoReply(&buf, &buf));
}

test "icmp error quotes header and eight bytes" {
    const ipv4_mod = @import("ipv4.zig");
    var packet: [64]u8 = undefined;
    const n = try ipv4_mod.write(
        &packet,
        try @import("../types.zig").Ipv4.parse("10.0.1.2"),
        try @import("../types.zig").Ipv4.parse("10.0.2.2"),
        ipv4_mod.Protocol.udp,
        64,
        1,
        "0123456789",
    );

    var msg: [64]u8 = undefined;
    const m = try writeError(&msg, Type.destination_unreachable, Code.host_unreachable, packet[0..n], 0);

    try testing.expectEqual(@as(usize, 8 + 20 + 8), m);
    try testing.expectEqual(Type.destination_unreachable, msg[0]);
    try testing.expectEqual(Code.host_unreachable, msg[1]);
    try testing.expectEqual(@as(u16, 0), ipv4_mod.checksum(msg[0..m]));
    try testing.expectEqualSlices(u8, packet[0..28], msg[8..m]);
}

test "icmp frag-needed carries mtu" {
    const ipv4_mod = @import("ipv4.zig");
    var packet: [32]u8 = undefined;
    const n = try ipv4_mod.write(
        &packet,
        try @import("../types.zig").Ipv4.parse("10.0.1.2"),
        try @import("../types.zig").Ipv4.parse("10.0.2.2"),
        ipv4_mod.Protocol.udp,
        64,
        1,
        "x",
    );

    var msg: [64]u8 = undefined;
    const m = try writeError(&msg, Type.destination_unreachable, Code.frag_needed, packet[0..n], 1400);
    try testing.expect(m > 0);
    try testing.expectEqual(@as(u32, 1400), (@as(u32, msg[4]) << 24) | (@as(u32, msg[5]) << 16) | (@as(u32, msg[6]) << 8) | msg[7]);
}

test "icmp checksum shape" {
    var buf: [16]u8 = undefined;
    const n = try writeEchoRequest(&buf, 1, 1, "abc");
    try testing.expectEqual(@as(u16, 0), ipv4.checksum(buf[0..n]));
}
